{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: казначейское сопровождение концессий и ГЧП", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Концессионное соглашение", "description": "Договор по Закону № 115-ФЗ, по которому концессионер создаёт или реконструирует объект, принадлежащий концеденту (государству, муниципалитету), и эксплуатирует его."}, {"@type": "DefinedTerm", "name": "Соглашение о ГЧП (МЧП)", "description": "Договор по Закону № 224-ФЗ между публичным и частным партнёрами о создании объекта инфраструктуры; в отличие от концессии допускает частную собственность на объект."}, {"@type": "DefinedTerm", "name": "Капитальный грант", "description": "Финансирование концедентом части расходов на создание или реконструкцию объекта на инвестиционном этапе; не может превышать 80% таких расходов (ст. 10.1 Закона № 115-ФЗ)."}, {"@type": "DefinedTerm", "name": "Плата концедента", "description": "Возмещение или финансовое обеспечение расходов концессионера на этапе эксплуатации объекта, включая техническое обслуживание."}, {"@type": "DefinedTerm", "name": "Минимальный гарантированный доход", "description": "Форма участия концедента: возмещение недополученных доходов от эксплуатации до определённого соглашением уровня."}, {"@type": "DefinedTerm", "name": "Каскад сопровождения", "description": "Распространение казначейского сопровождения на контракты нижних уровней, источником оплаты которых являются сопровождаемые средства (ст. 242.23 БК)."}, {"@type": "DefinedTerm", "name": "Расходная декларация", "description": "Информация о структуре цены контракта (суммы средств соглашения), формируемая в установленных Правительством случаях по форме Минфина; основа проверки затрат при расширенном сопровождении."}]}
